                        <p className="text-sm text-gray-400">Verified Customer</p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </div>
        </section>
      )}
      {/* FAQ Section */}
      {service.faq && service.faq.length > 0 && (
        <section className="py-20 px-4 bg-gray-900">
          <div className="max-w-4xl mx-auto">
            <h2 className="text-4xl font-bold text-center mb-12">Frequently Asked Questions</h2>
            <Accordion type="single" collapsible>
              {service.faq.map((item, index) => (
                <AccordionItem key={index} value={`item-${index}`} className="border-gray-800">
                  <AccordionTrigger className="text-left text-lg font-semibold hover:text-green-400">
                    {item.question}
                  </AccordionTrigger>
                  <AccordionContent className="text-gray-300 text-base leading-relaxed">
                    {item.answer}
                  </AccordionContent>
                </AccordionItem>
              ))}
            </Accordion>
          </div>
        </section>
      )}
      {/* Guarantee Section */}
      {service.guaranteeText && (
        <section className="py-20 px-4">
          <div className="max-w-4xl mx-auto text-center">
            <Shield className="w-16 h-16 text-green-400 mx-auto mb-6" />
            <h2 className="text-3xl font-bold mb-6">Our Guarantee</h2>
            <p className="text-xl text-gray-300 leading-relaxed">{service.guaranteeText}</p>
          </div>
        </section>
      )}
      {/* Final CTA Section */}
      <section className="py-20 px-4 bg-gradient-to-r from-green-600 to-green-800">
        <div className="max-w-4xl mx-auto text-center">
          <h2 className="text-4xl font-bold mb-6">Ready to Transform Your Car?</h2>
          <p className="text-xl mb-8 opacity-90">
            Book your {service.title.toLowerCase()} today and experience the P91 difference!
          </p>

          <div className="mb-8">
            <div className="flex items-center justify-center gap-4 mb-4">
              <span className="text-4xl font-bold">₹{service.price}</span>
              {service.originalPrice && (
                <>
                  <span className="text-2xl opacity-75 line-through">₹{service.originalPrice}</span>
                  <Badge className="bg-black text-green-400">Save {discountPercent}%</Badge>
                </>
              )}
            </div>
            {service.urgencyText && (
              <p className="text-black font-semibold animate-pulse">{service.urgencyText}</p>
            )}
          </div>

          <Button
            size="lg"
            onClick={() => setBookingModalOpen(true)}
            className="bg-black hover:bg-gray-900 text-green-400 font-bold px-12 py-4 text-xl"
            data-testid="button-book-now-final"
          >
            {service.ctaText || "Book Now"}
            <ArrowRight className="ml-2 w-6 h-6" />
          </Button>

          {/* Contact Info */}
          <div className="mt-12 flex flex-wrap justify-center gap-8 text-sm opacity-90">
            <div className="flex items-center gap-2">
              <Phone className="w-4 h-4" />
              +91 74066 19191
            </div>
            <div className="flex items-center gap-2">
              <Mail className="w-4 h-4" />
              info@p91carcare.com
            </div>
            <div className="flex items-center gap-2">
              <MapPin className="w-4 h-4" />
              Bangalore, Karnataka
            </div>
          </div>
        </div>
      </section>
      {/* Floating FOMO CTA Button */}
      {showFloatingCTA && !bookingModalOpen && (
        <div 
          className={`fixed bottom-20 sm:bottom-6 left-1/2 transform -translate-x-1/2 z-[45] transition-all duration-500 ease-in-out ${
            showFloatingCTA ? 'translate-y-0 opacity-100' : 'translate-y-full opacity-0'
          }`}
          data-testid="floating-cta-button"
          style={{ pointerEvents: 'auto' }}
        >
          <div className="bg-gradient-to-r from-red-500 via-red-600 to-orange-600 rounded-2xl shadow-2xl px-4 py-3 mx-4 max-w-xs relative border border-red-400/30">
            <div className="flex items-center justify-between gap-3">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <div className="w-2 h-2 bg-white rounded-full animate-pulse"></div>
                  <span className="text-white text-xs font-bold tracking-wide uppercase">
                    Limited Slots
                  </span>
                </div>
                <div className="text-white text-sm font-semibold">
                  {service.title === 'Annual Maintenance Package' ? 'Book now for ₹8999' : 'Book now for ₹299'}
                </div>
              </div>
              <Button
                onClick={(e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setBookingModalOpen(true);
                }}
                className="bg-white hover:bg-gray-100 text-red-600 font-bold px-4 py-2 rounded-xl shadow-lg transform hover:scale-105 transition-all duration-200 flex items-center gap-2 min-w-fit relative z-10 border-2 border-white"
                data-testid="button-floating-book-now"
              >
                <Zap className="w-4 h-4" />
                <span className="text-sm font-bold">BOOK</span>
              </Button>
            </div>

            {/* Subtle Glow Effect */}
            <div className="absolute inset-0 rounded-2xl bg-gradient-to-r from-red-500 via-red-600 to-orange-600 opacity-40 blur-sm -z-10"></div>
          </div>

          {/* Enhanced Save Badge */}
          {service?.originalPrice && parseFloat(service.originalPrice) > parseFloat(service.price) && (
            <div className="absolute -top-2 -right-2 bg-yellow-400 text-black text-xs font-bold px-3 py-1 rounded-full shadow-lg border-2 border-white animate-bounce">
              Save ₹{(parseFloat(service.originalPrice) - parseFloat(service.price)).toLocaleString()}
            </div>
          )}
        </div>
      )}
      {/* Booking Modal */}
      <BookingModal
        isOpen={bookingModalOpen}
        onClose={() => setBookingModalOpen(false)}
        service={service}
      />
    </div>
  );
}

