server/services/payment.ts.content:
import Razorpay from "razorpay";
import crypto from "crypto";

let razorpay: Razorpay | null = null;

try {
  const keyId = process.env.RAZORPAY_KEY_ID || process.env.RAZORPAY_TEST_KEY_ID;
  const keySecret = process.env.RAZORPAY_KEY_SECRET || process.env.RAZORPAY_TEST_KEY_SECRET;

  if (keyId && keySecret) {
    razorpay = new Razorpay({
      key_id: keyId,
      key_secret: keySecret,
    });
  } else {
    console.warn("Razorpay credentials not found. Payment functionality will be disabled.");
  }
} catch (error) {
  console.error("Failed to initialize Razorpay:", error);
}

export interface PaymentOrder {
  id: string;
  amount: number;
  currency: string;
  receipt: string;
}

export async function createPaymentOrder(amount: number, receipt: string): Promise<PaymentOrder> {
  if (!razorpay) {
    throw new Error("Payment service not configured. Please set up Razorpay credentials.");
  }

  try {
    const order = await razorpay.orders.create({
      amount: Math.round(Number(amount) * 100), // Convert to paise
      currency: "INR",
      receipt,
      payment_capture: true, // Auto-capture payments
    });

    return {
      id: order.id,
      amount: order.amount,
      currency: order.currency,
      receipt: order.receipt || receipt,
    };
  } catch (error) {
    console.error("Razorpay order creation error:", error);
    throw new Error("Failed to create payment order");
  }
}

export async function verifyPaymentSignature(
  orderId: string,
  paymentId: string,
  signature: string
): Promise<boolean> {
  try {
    const body = orderId + "|" + paymentId;
    const keySecret = process.env.RAZORPAY_KEY_SECRET;

    console.log("Verifying payment signature with order:", orderId, "payment:", paymentId);
    console.log("Using key secret:", keySecret ? "Present" : "Missing");

    if (!keySecret) {
      console.error("RAZORPAY_KEY_SECRET not found");
      return false;
    }

    const expectedSignature = crypto
      .createHmac("sha256", keySecret)
      .update(body.toString())
      .digest("hex");

    console.log("Expected signature:", expectedSignature);
    console.log("Received signature:", signature);
    console.log("Signature match:", expectedSignature === signature);

    return expectedSignature === signature;
  } catch (error) {
    console.error("Payment verification error:", error);
    return false;
  }
}

client/src/lib/razorpay.ts.content:
declare global {
  interface Window {
    Razorpay: any;
  }
}

export async function loadRazorpay(): Promise<any> {
  return new Promise((resolve, reject) => {
    // Check if already loaded
    if (window.Razorpay) {
      console.log("Razorpay already available");
      resolve(window.Razorpay);
      return;
    }

    console.log("Loading Razorpay script...");

    // Remove any existing CSP restrictions
    const cspMetas = document.querySelectorAll('meta[http-equiv="Content-Security-Policy"]');
    cspMetas.forEach(meta => meta.remove());

    const script = document.createElement("script");
    script.src = "https://checkout.razorpay.com/v1/checkout.js";
    script.async = true;
    script.crossOrigin = "anonymous";

    script.onload = () => {
      console.log("Razorpay script loaded successfully");
      if (window.Razorpay) {
        resolve(window.Razorpay);
      } else {
        console.error("Razorpay object not found after load");
        reject(new Error("Razorpay object not available"));
      }
    };

    script.onerror = (error) => {
      console.error("Failed to load Razorpay script:", error);
      reject(new Error("Failed to load Razorpay script"));
    };

    document.head.appendChild(script);

    // Add timeout for safety
    setTimeout(() => {
      if (!window.Razorpay) {
        console.error("Razorpay load timeout");
        reject(new Error("Razorpay load timeout"));
      }
    }, 15000);
  });
}

